func Reconcile(ctx context.Context, req Request) (Result, error) {
    // 1. OBSERVE — read desired state from the API
    desired := apiClient.Get(req.NamespacedName)  // the CR
    if notFound(desired) {
        return OK  // object was deleted; nothing to do
    }

    // 2. OBSERVE — read actual state from the cluster
    actual := apiClient.Get(childResourceName(desired))

    // 3. DIFF — compare desired vs actual
    if actual == nil {
        // resource does not exist yet
        child := buildChildResource(desired.Spec)
        err := apiClient.Create(child)
        return requeueOnError(err)
    }

    if needsUpdate(desired.Spec, actual.Spec) {
        patch := computePatch(desired.Spec, actual.Spec)
        err := apiClient.Patch(actual, patch)
        return requeueOnError(err)
    }

    // 4. UPDATE STATUS to reflect observed state
    desired.Status.Ready = actual.Status.Ready
    apiClient.Status().Update(desired)

    return OK  // diff is zero; nothing more to do
}

