func (r *FooReconciler) Reconcile(ctx context.Context, req ctrl.Request) (ctrl.Result, error) {
    foo := &Foo{}
    r.Get(ctx, req.NamespacedName, foo)

    if foo.DeletionTimestamp.IsZero() {
        // Object is not being deleted. Ensure our finalizer is present.
        if !containsString(foo.Finalizers, myFinalizer) {
            foo.Finalizers = append(foo.Finalizers, myFinalizer)
            r.Update(ctx, foo)
        }
    } else {
        // Object is being deleted.
        if containsString(foo.Finalizers, myFinalizer) {
            // Run cleanup: delete S3 bucket, revoke IAM role, etc.
            if err := r.deleteExternalResources(foo); err != nil {
                return ctrl.Result{}, err  // retry until cleanup succeeds
            }
            // Remove our finalizer to unblock deletion.
            foo.Finalizers = removeString(foo.Finalizers, myFinalizer)
            r.Update(ctx, foo)
        }
